"""Generate frontend/src/shared/data/countries.ts from pycountry, the backend's source of truth.

python -m scripts.generate_countries_ts
"""

import json
from pathlib import Path

import pycountry

OUTPUT = (
    Path(__file__).resolve().parents[2] / "frontend" / "src" / "shared" / "data" / "countries.ts"
)


def main() -> None:
    countries = sorted(
        (
            {"code": c.alpha_2, "name": getattr(c, "common_name", None) or c.name}
            for c in pycountry.countries
        ),
        key=lambda c: c["name"],
    )
    lines = [
        "// Generated by backend/scripts/generate_countries_ts.py. Do not edit by hand.",
        "export const COUNTRIES: ReadonlyArray<{ code: string; name: string }> = [",
        *(
            f"  {{ code: {json.dumps(c['code'])}, name: {json.dumps(c['name'])} }},"
            for c in countries
        ),
        "]",
        "",
    ]
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_text("\n".join(lines), encoding="utf-8")


if __name__ == "__main__":
    main()
